-- Out-of-range sale with NULL PRODUCT_ID (allowed by FK), which NULL-poisons NOT IN in Q2
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (NULL, 20, 200, DATE '2018-12-31', 1, 50);

